import * as THREE from 'three';

const canvas=document.querySelector('#world');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.05;
const scene=new THREE.Scene();scene.background=new THREE.Color(0x9ab8c6);scene.fog=new THREE.Fog(0x9ab8c6,100,480);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,900);
const hemi=new THREE.HemisphereLight(0xc9e6f4,0x596257,2.1);scene.add(hemi);
const sun=new THREE.DirectionalLight(0xffdfad,3.3);sun.position.set(-80,120,40);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-120;sun.shadow.camera.right=120;sun.shadow.camera.top=120;sun.shadow.camera.bottom=-120;sun.shadow.bias=-.0002;scene.add(sun);
const mat=(color,roughness=.85,metalness=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness});
const mats={road:mat(0x303b40),sidewalk:mat(0x9a9a8b),grass:mat(0x69785d),building:[0x617580,0x8c8173,0x9c9b8e,0x5c6e75,0xc0ad8e,0x727c79].map(c=>mat(c)),glass:[0x345367,0x47677a,0x748b8d,0x8c9d99].map(c=>mat(c,.35,.34)),window:mat(0xdcbf7c,.32,.15),white:mat(0xe4ddca),yellow:mat(0xe8b569),dark:mat(0x222c30),skin:mat(0xb87f5b),shirt:mat(0x374b51),pants:mat(0x232e31),car:mat(0xc28b46,.3,.48),tire:mat(0x202426),leaf:mat(0x61745b),trunk:mat(0x594a38),water:mat(0x397d91,.24,.25)};
function box(parent,x,y,z,w,h,d,material,cast=true,receive=true){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);m.position.set(x,y,z);m.castShadow=cast;m.receiveShadow=receive;parent.add(m);return m}
const ground=box(scene,0,-.7,0,1000,1,1000,mats.grass,false,true);
// Coastal promenade and ocean
box(scene,0,-.25,254,1000,.4,250,mats.water,false,false);
box(scene,0,-.1,130,1000,.24,32,mat(0xc5b99d),false,false);
box(scene,0,.01,109,1000,.12,12,mat(0xada58e),false,false);
// City blocks: tiled streets, avenues, parks, landmark districts
const blockSize=56, cityExtent=280;
for(let x=-cityExtent;x<=cityExtent;x+=blockSize){for(let z=-cityExtent;z<=cityExtent;z+=blockSize){
  const avenue=Math.abs(x)<30||Math.abs(z)<30;
  if(avenue){box(scene,x,-.1,z,avenue&&Math.abs(x)<30?23:56,.22,avenue&&Math.abs(z)<30?23:56,mats.road,false);continue;}
  const park=(Math.abs(x-140)<28&&Math.abs(z-84)<28)||(Math.abs(x+140)<28&&Math.abs(z+140)<28);
  if(park){box(scene,x,-.05,z,51,.1,51,mat(0x586b4d),false);for(let i=0;i<9;i++)makeTree(x+(Math.random()-.5)*43,z+(Math.random()-.5)*43);continue;}
  box(scene,x,-.08,z,54,.16,54,mat(0x464d4b),false);
  const count=3+Math.floor(Math.random()*3);
  for(let n=0;n<count;n++){
    const px=x+(Math.random()-.5)*43,pz=z+(Math.random()-.5)*42;
    const central=(Math.abs(x)<145&&Math.abs(z)<145);let floors=central?7+Math.random()*16:3+Math.random()*8;
    if(Math.random()<.12&&central)floors=23+Math.random()*13;
    const w=9+Math.random()*10,d=9+Math.random()*10,h=floors*2.7;
    const building=new THREE.Group();building.position.set(px,0,pz);scene.add(building);
    const shellmat=mats.building[Math.floor(Math.random()*mats.building.length)];box(building,0,h/2,0,w,h,d,shellmat);
    // Dense but instanced-looking architectural bands and window grids.
    const glassmat=mats.glass[Math.floor(Math.random()*mats.glass.length)];
    const rows=Math.floor(h/2.5),cols=Math.max(2,Math.floor(w/2.1));
    for(let row=1;row<rows;row++){for(let col=0;col<cols;col++){
      const wx=-w/2+.9+col*(w-1.6)/cols,wy=row*2.35;
      if(w>12&&Math.random()<.14)continue;
      box(building,wx,wy,d/2+.012,.72,1.15,.035,Math.random()<.13?mats.window:glassmat,false,false);
      box(building,wx,wy,-d/2-.012,.72,1.15,.035,glassmat,false,false);
      box(building,w/2+.012,wy,wx,.035,1.15,.72,glassmat,false,false);
      box(building,-w/2-.012,wy,wx,.035,1.15,.72,glassmat,false,false);
    }}
    if(h>46){box(building,0,h+.5,0,w*.45,1,d*.45,mat(0x313d40));}
  }
  // sidewalk edging and occasional street trees
  if(Math.random()<.32)makeTree(x+18,z+18);
}}
// Main roads and intersection lane markings
for(let k=-280;k<=280;k+=56){for(let p=-270;p<270;p+=19){box(scene,k,.025,p,0.22,.035,7,mat(0xd3caa7),false,false);box(scene,p,.026,k,7,.035,.22,mat(0xd3caa7),false,false)}}
// Boulevard, ramps and elevated freeway ribbons
for(let lane=-1;lane<=1;lane++){box(scene,lane*4,.08,0,2.5,.04,560,mat(0xe8dec0),false,false)}
const highway=new THREE.Group();scene.add(highway);
for(let i=0;i<16;i++){const z=-235+i*31;box(highway,-80,10,z,102,.65,9,mats.road);box(highway,-80,9.3,z-4.8,102,.25,.5,mat(0xa6a295));box(highway,-80,9.3,z+4.8,102,.25,.5,mat(0xa6a295));for(let j=0;j<7;j++)box(highway,-125+j*15,10.36,z,5,.035,.13,mat(0xd5cba9),false,false)}
// Pier extends into Pacific
box(scene,-65,.25,195,14,.5,130,mat(0x877254));for(let z=145;z<258;z+=13){for(let x=-71;x<=-59;x+=12)box(scene,x,-1,z,1,3,1,mat(0x5e4936))}for(let i=0;i<7;i++)box(scene,-65,.65,150+i*16,13,.25,.6,mat(0xdec991));
// airport runway at east side
box(scene,360,-.12,-80,145,.24,500,mat(0x313a3d),false);for(let z=-310;z<170;z+=30)box(scene,360,.02,z,2,.035,14,mat(0xf0e9ce),false,false);for(let x of [315,405])box(scene,x,.02,-80,1,.04,490,mat(0xddd4bc),false,false);
for(let i=0;i<4;i++){const hang=box(scene,300+i*38,9,180,30,18,24,mat(0x8c9088));box(scene,300+i*38,18,180,32,2,27,mat(0x5a6769))}
// mountain silhouettes behind city
for(let i=0;i<19;i++){const x=-450+i*50;const h=45+Math.random()*90;const m=new THREE.Mesh(new THREE.ConeGeometry(40+Math.random()*30,h,5),mat(i%2?0x667c78:0x75837a));m.position.set(x,h/2-2,-400-Math.random()*35);scene.add(m)}
// vegetation
function makeTree(x,z){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);const trunk=box(g,0,2.2,0,.65,4.4,.65,mats.trunk);const crown=new THREE.Mesh(new THREE.IcosahedronGeometry(2.6,1),mats.leaf);crown.position.y=5.4;crown.castShadow=true;g.add(crown);}
// Character and vehicle models
function createCharacter(){const g=new THREE.Group();const body=box(g,0,1.25,0,.72,.92,.4,mats.shirt);const head=new THREE.Mesh(new THREE.SphereGeometry(.25,12,10),mats.skin);head.position.y=1.95;head.castShadow=true;g.add(head);const legs=[];for(const x of [-.2,.2]){legs.push(box(g,x,.48,0,.23,.72,.26,mats.pants));box(g,x,.12,.08,.28,.16,.4,mats.dark)}for(const x of [-.49,.49])box(g,x,1.28,0,.18,.72,.2,mats.skin);g.position.set(0,0,15);scene.add(g);g.userData.legs=legs;return g}
const player=createCharacter();
function createCar(color=0xc28b46){const g=new THREE.Group();const paint=mat(color,.28,.55),glass=mat(0x607d88,.25,.35);box(g,0,.62,0,2.25,.65,4.25,paint);box(g,0,1.15,-.2,1.8,.72,2.2,paint);box(g,0,1.2,-.18,1.67,.53,2.05,glass,false);for(const x of [-1,1])for(const z of [-1.4,1.4]){const wheel=new THREE.Mesh(new THREE.CylinderGeometry(.42,.42,.25,16),mats.tire);wheel.rotation.z=Math.PI/2;wheel.position.set(x*1.04,.42,z);wheel.castShadow=true;g.add(wheel)}for(const x of [-.7,.7])box(g,x,.65,2.13,.37,.18,.08,mats.window);box(g,0,.73,-2.14,.9,.13,.06,mat(0xc44834));g.position.y=.12;g.userData.speed=0;return g}
const playerCar=createCar();playerCar.position.set(4,0,14);scene.add(playerCar);
const traffic=[];const carColors=[0x426975,0xd3d0c0,0x973e32,0x555e58,0xb7a276,0x464c66];
for(let i=0;i<18;i++){const c=createCar(carColors[i%carColors.length]);const lane=i%4;const axis=lane<2?'x':'z';const sign=i%2?1:-1;c.userData.axis=axis;c.userData.sign=sign;c.userData.speed=6+Math.random()*8;if(axis==='x'){c.position.set((Math.random()-.5)*520,0,lane===0?-8:8);c.rotation.y=sign>0?Math.PI/2:-Math.PI/2}else{c.position.set(lane===2?-8:8,0,(Math.random()-.5)*520);c.rotation.y=sign>0?0:Math.PI}scene.add(c);traffic.push(c)}
// Pedestrians: distinct wandering routes and simple idle behavior
const pedestrians=[];const npcColors=[0x8d6450,0x56766b,0x39475a,0xa28247,0x735e79];
for(let i=0;i<30;i++){const p=createCharacter();p.removeFromParent();p.traverse(o=>{if(o.isMesh&&o.material===mats.shirt)o.material=mat(npcColors[i%npcColors.length])});const a=Math.random()*Math.PI*2,r=25+Math.random()*150;p.position.set(Math.cos(a)*r,0,Math.sin(a)*r);p.userData={angle:Math.random()*6.28,pace:.35+Math.random()*.55,phase:Math.random()*6};scene.add(p);pedestrians.push(p)}
// Mission beacon and marker
const beacon=new THREE.Group();beacon.position.set(-65,0,237);scene.add(beacon);const ring=new THREE.Mesh(new THREE.TorusGeometry(2.1,.19,8,32),mats.yellow);ring.rotation.x=Math.PI/2;ring.position.y=.16;beacon.add(ring);const beam=new THREE.Mesh(new THREE.CylinderGeometry(.13,.5,5,12,1,true),new THREE.MeshBasicMaterial({color:0xf0b95f,transparent:true,opacity:.37,side:THREE.DoubleSide}));beam.position.y=3;beacon.add(beam);const orb=new THREE.Mesh(new THREE.SphereGeometry(.45,12,10),new THREE.MeshBasicMaterial({color:0xffd47e}));orb.position.y=5.7;beacon.add(orb);
// weather particles
const rainCount=800,rainGeo=new THREE.BufferGeometry(),rainPos=new Float32Array(rainCount*3);for(let i=0;i<rainCount;i++){rainPos[i*3]=(Math.random()-.5)*130;rainPos[i*3+1]=Math.random()*65;rainPos[i*3+2]=(Math.random()-.5)*130}rainGeo.setAttribute('position',new THREE.BufferAttribute(rainPos,3));const rain=new THREE.Points(rainGeo,new THREE.PointsMaterial({color:0xb8d8e6,size:.14,transparent:true,opacity:.55}));rain.visible=false;scene.add(rain);
const keys={};let activeVehicle=false,started=false,phoneOpen=false,missionDone=false,weatherMode=0,wantedLevel=0,gameTime=18.7,toastTimer=0,missionStart=performance.now();
const ui={clock:document.querySelector('#clock'),phone:document.querySelector('#phone'),phoneTime:document.querySelector('#phone-time'),phoneBig:document.querySelector('#phone-big-time'),modal:document.querySelector('#modal'),toast:document.querySelector('#toast'),speedCard:document.querySelector('#speed-card'),interaction:document.querySelector('#interaction')};
function toast(msg){ui.toast.textContent=msg;ui.toast.classList.add('show');toastTimer=2.8}
function togglePhone(){if(!started)return;phoneOpen=!phoneOpen;ui.phone.classList.toggle('open',phoneOpen);if(!phoneOpen)closeModal()}
function showModal(type){const title=document.querySelector('#modal-title'),content=document.querySelector('#modal-content');if(type==='map'){title.textContent='LOS SANTOS COUNTY';content.innerHTML='<p>One city. A thousand ways through it. Your gold marker is waiting at the old pier.</p><div class="map-legend"><span><b>◆</b> ACTIVE OBJECTIVE</span><span><b>●</b> YOU ARE HERE</span><span><b>▰</b> GARAGE · DOWNTOWN</span><span><b>〰</b> PACIFIC COAST</span></div>'}else if(type==='missions'){title.textContent='YOUR STORY';content.innerHTML='<div class="mission-row"><strong>01 · A City of Opportunity</strong><small>Meet Rico at the Pacific Pier · '+(missionDone?'COMPLETED':'IN PROGRESS')+'</small></div><div class="mission-row"><strong>02 · The Long Way Home</strong><small>Available after your first meeting · LOCKED</small></div><div class="mission-row"><strong>SIDE WORK · Quick Getaway</strong><small>Find a vehicle and explore the city.</small></div>'}else if(type==='weather'){title.textContent='CITY CONDITIONS';content.innerHTML='<p>Weather moves across the county in real time. Choose the forecast that fits your ride.</p><div class="map-legend"><span><b>☼</b> SUNSHINE</span><span><b>☁</b> OVERCAST</span><span><b>ϟ</b> RAINSTORM</span></div><p>Current: '+document.querySelector('#weather-label').textContent+'. Tap the weather app again to cycle conditions.</p>'}else{title.textContent='PERSONAL GARAGE';content.innerHTML='<p>Your garage is your home base. Select a paint finish before heading out.</p><div class="garage-row"><strong>VAPID DOMINATOR · COUPE</strong><small>RWD · 0–100 KM/H IN 5.2 SEC</small><div class="map-legend"><span data-color="0xc28b46"><b>●</b> DESERT GOLD</span><span data-color="0x296f79"><b>●</b> PACIFIC TEAL</span><span data-color="0x862f32"><b>●</b> CRIMSON</span></div></div>'}ui.modal.classList.add('open')}
function closeModal(){ui.modal.classList.remove('open')}
document.querySelectorAll('.phone-grid button').forEach(b=>b.addEventListener('click',()=>{const app=b.dataset.app;if(app==='weather'){weatherMode=(weatherMode+1)%3;setWeather();}showModal(app)}));document.querySelector('#phone-close').onclick=togglePhone;document.querySelector('#modal-close').onclick=closeModal;ui.modal.addEventListener('click',e=>{if(e.target===ui.modal)closeModal()});document.querySelector('#modal-content').addEventListener('click',e=>{const el=e.target.closest('[data-color]');if(el){const c=Number(el.dataset.color);playerCar.traverse(o=>{if(o.isMesh&&o.material.color)o.material.color.setHex(c)})}});
function setWeather(){const colors=[0x9ab8c6,0x788b91,0x334553],fog=[0x9ab8c6,0x788b91,0x334553];scene.background.setHex(colors[weatherMode]);scene.fog.color.setHex(fog[weatherMode]);rain.visible=weatherMode===2;hemi.intensity=weatherMode===2?1.1:weatherMode===1?1.55:2.1;sun.intensity=weatherMode===2?.8:weatherMode===1?1.8:3.3;document.querySelector('#weather-label').textContent=['SUNNY','OVERCAST','STORM'][weatherMode];toast(['SUNSHINE · CLEAR ROADS','OVERCAST · LOW VISIBILITY','STORM FRONT · WET ROADS'][weatherMode])}
function setWanted(n){wantedLevel=Math.max(0,Math.min(5,n));document.querySelector('#wanted').classList.toggle('active',wantedLevel>0);document.querySelectorAll('.stars b').forEach((s,i)=>{s.textContent=i<wantedLevel?'★':'☆';s.classList.toggle('on',i<wantedLevel)})}
function toggleVehicle(){if(!started)return;if(activeVehicle){activeVehicle=false;player.visible=true;player.position.set(playerCar.position.x+2,0,playerCar.position.z);player.rotation.y=playerCar.rotation.y;playerCar.userData.speed=0;ui.speedCard.classList.remove('show');toast('ON FOOT · EXPLORE THE CITY');return}if(player.position.distanceTo(playerCar.position)<5){activeVehicle=true;player.visible=false;ui.speedCard.classList.add('show');toast('VAPID DOMINATOR · READY TO DRIVE')}}
function startGame(){started=true;document.querySelector('#intro').classList.add('hidden');toast('WELCOME TO LOS SANTOS · FIND THE GOLD MARKER');}
document.querySelector('#start-game').onclick=startGame;window.addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(e.key.toLowerCase()))e.preventDefault();if(e.repeat)return;if(e.key.toLowerCase()==='m')togglePhone();if(e.key.toLowerCase()==='e')toggleVehicle();if(e.key===' '&&!activeVehicle&&started){player.position.y=.65;setTimeout(()=>player.position.y=0,450)}if(e.key.toLowerCase()==='r'){weatherMode=(weatherMode+1)%3;setWeather()}if(e.key==='Escape'){phoneOpen=false;ui.phone.classList.remove('open');closeModal()}});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
document.querySelectorAll('.move-pad button').forEach(b=>{const k=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();keys[k]=true;b.setPointerCapture(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>keys[k]=false))});document.querySelector('[data-action="interact"]').addEventListener('pointerdown',e=>{e.preventDefault();toggleVehicle()});document.querySelector('[data-action="jump"]').addEventListener('pointerdown',e=>{e.preventDefault();if(!activeVehicle){player.position.y=.65;setTimeout(()=>player.position.y=0,450)}});
// map rendering
const mapCanvas=document.querySelector('#minimap'),ctx=mapCanvas.getContext('2d');function drawMap(){const w=mapCanvas.width,h=mapCanvas.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#25373a';ctx.fillRect(0,0,w,h);ctx.save();ctx.translate(w/2-player.position.x*.27,h/2-player.position.z*.27);ctx.scale(.27,.27);ctx.fillStyle='#3b6670';ctx.fillRect(-500,120,1000,250);ctx.fillStyle='#b9aa89';ctx.fillRect(-500,110,1000,15);ctx.fillStyle='#535b59';for(let x=-280;x<=280;x+=56){for(let z=-280;z<=280;z+=56){ctx.fillRect(x-25,z-25,50,50)}}ctx.fillStyle='#c9c4a6';for(let p=-500;p<500;p+=35){ctx.fillRect(-4,p,1,11);ctx.fillRect(p,-4,11,1)}ctx.fillStyle='#db9d56';ctx.beginPath();ctx.arc(-65,237,8,0,7);ctx.fill();ctx.restore();ctx.fillStyle='#e7b66e';ctx.beginPath();ctx.arc(w/2,h/2,4,0,7);ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(w/2,h/2-9);ctx.lineTo(w/2-5,h/2+5);ctx.lineTo(w/2+5,h/2+5);ctx.closePath();ctx.stroke();}
let last=performance.now(),frame=0;function animate(now){requestAnimationFrame(animate);const dt=Math.min(.04,(now-last)/1000);last=now;frame++;gameTime=(gameTime+dt*.018)%24;const hour=Math.floor(gameTime),minute=Math.floor((gameTime-hour)*60),time=`${String(hour).padStart(2,'0')}:${String(minute).padStart(2,'0')}`;ui.clock.textContent=time;ui.phoneTime.textContent=time;ui.phoneBig.textContent=time;
const daylight=Math.max(0,Math.sin((gameTime-6)/12*Math.PI));sun.position.set(-80,40+daylight*100,40);sun.intensity=(.2+daylight*3.1)*(weatherMode===2?.3:weatherMode===1?.65:1);hemi.intensity=.45+daylight*(weatherMode===2?.7:1.75);scene.fog.near=weatherMode===2?55:100;scene.fog.far=weatherMode===2?250:480;const sky=weatherMode===2?new THREE.Color(0x344653):new THREE.Color(0x172b42).lerp(new THREE.Color(0x9ab8c6),.2+daylight*.8);scene.background.copy(sky);scene.fog.color.copy(sky);if(daylight<.32){renderer.toneMappingExposure=.72;document.querySelector('#weather-label').style.color='#e8a96a'}else{renderer.toneMappingExposure=1.05;document.querySelector('#weather-label').style.color=''}
if(started&&!phoneOpen){if(activeVehicle){const c=playerCar,forward=(keys.w?1:0)-(keys.s?1:0),turn=(keys.d?1:0)-(keys.a?1:0);c.userData.speed=THREE.MathUtils.damp(c.userData.speed,forward*25,1.25,dt);c.rotation.y-=turn*dt*(.85+Math.abs(c.userData.speed)*.035);const v=new THREE.Vector3(Math.sin(c.rotation.y),0,Math.cos(c.rotation.y));c.position.addScaledVector(v,c.userData.speed*dt);c.position.x=THREE.MathUtils.clamp(c.position.x,-480,480);c.position.z=THREE.MathUtils.clamp(c.position.z,-480,300);document.querySelector('#speed').textContent=Math.round(Math.abs(c.userData.speed)*3.6);document.querySelector('#speed-line').style.width=Math.min(100,Math.abs(c.userData.speed)*3.2)+'%';if(Math.abs(c.userData.speed)>23&&Math.random()<dt*.55)setWanted(Math.max(1,wantedLevel));}
else{const move=new THREE.Vector3((keys.d?1:0)-(keys.a?1:0),0,(keys.s?1:0)-(keys.w?1:0));if(move.lengthSq()){move.normalize();const speed=keys.shift?8:4.7;player.position.addScaledVector(move,speed*dt);player.rotation.y=Math.atan2(move.x,move.z);player.userData.legs.forEach((l,i)=>l.rotation.x=Math.sin(now*.012+i*Math.PI)*.52)}else player.userData.legs.forEach(l=>l.rotation.x=THREE.MathUtils.damp(l.rotation.x,0,8,dt));player.position.x=THREE.MathUtils.clamp(player.position.x,-480,480);player.position.z=THREE.MathUtils.clamp(player.position.z,-480,300);}
}
traffic.forEach(c=>{if(!activeVehicle||c!==playerCar){const axis=c.userData.axis;c.position[axis]+=c.userData.sign*c.userData.speed*dt;if(Math.abs(c.position[axis])>285)c.position[axis]*=-.96;}});pedestrians.forEach(p=>{p.userData.angle+=Math.sin(now*.0003+p.userData.phase)*dt*.16;const pace=p.userData.pace;p.position.x+=Math.cos(p.userData.angle)*pace*dt;p.position.z+=Math.sin(p.userData.angle)*pace*dt;if(Math.abs(p.position.x)>250||Math.abs(p.position.z)>250)p.userData.angle+=Math.PI;p.rotation.y=p.userData.angle;p.userData.legs.forEach((l,i)=>l.rotation.x=Math.sin(now*.004*p.userData.pace+i*Math.PI)*.24)});
